```solidity
function deposit(IERC20 _collateralToken, uint256 _amount) external {
    // Transfer collateral token to this contract
    _collateralToken.safeTransferFrom(msg.sender, address(this), _amount);

    // Calculate ezETH to mint based on the value of the deposit
    uint256 ezETHToMint = renzoOracle.calculateMintAmount(
        totalTVL,
        collateralTokenValue,
        ezETH.totalSupply()
    );

